                    "sql": "CREATE TABLE IF NOT EXISTS thd-pharma-wh.MAPLEMONK.thd_pharma_wh_ga_sessions_consolidated ( date DATE, shop_name STRING, Channel STRING, sessions INT64, Brand STRING ); Create or replace table thd-pharma-wh.MAPLEMONK.thd_pharma_wh_Sales_Cost_Source as with Sessions as ( select date date, channel marketing_channel, case when lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONE SIGNATURE\' else UPPER(SHOP_NAME) end marketplace, Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand, sum(sessions) Sessions from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_ga_sessions_consolidated group by 1,2,3,4 ), returnsales as ( select cast(return_date as date) return_date ,marketing_channel ,case when lower(marketplace) like any (\'%amazon%\') then \'AMAZON\' when lower(marketplace) like any (\'%shopify%\') and lower(brand) like \'%dream%\' then \'SHOPIFY - DB\' when lower(marketplace) like any (\'%shopify%\') and lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' else upper(marketplace) end as marketplace ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as brand ,sum(total_return_amount) TOTAL_RETURN_AMOUNT ,sum(total_return_amount_excl_tax) TOTAL_RETURN_AMOUNT_EXCL_TAX ,sum(total_returned_quantity) TOTAL_RETURNED_QUANTITY from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_RETURNS_CONSOLIDATED group by 1,2,3,4 order by 1 desc ), orders as ( select cast(FI.order_date as date) Date ,upper(marketplace) Marketplace ,upper(FI.CHANNEL) marketing_CHANNEL ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand ,upper(FI.product_sub_category) as Sub_Category ,count(distinct FI.commonsku) as Number_Of_SKU ,sum(ifnull(FI.COGS_Value,0)) as Sum_Of_COGS ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) Total_Sales ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(case when (lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') then ifnull(FI.SELLING_PRICE,0) else 0 end),0) TOTAL_SALES_EXCL_CANCL , ifnull(sum(Case when Lower(order_status) like \'%pending%\' then ifnull(FI.Selling_price,0) else 0 end),0) as Pending_Sales ,count(distinct FI.order_id) Total_Orders ,count(distinct FI.order_id) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.order_id end) Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) as New_Customer_Orders ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') then FI.order_id end)) as New_Customer_Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) as Total_New_Customers ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end)) New_Customers_EXCL_CANCL ,count(distinct FI.customer_id_final) as TOTAL_Unique_Customers ,(count(distinct FI.customer_id_final) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.customer_id_final end)) as Unique_Customers_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) as Repeat_Customers ,(count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end))) Repeat_Customers_EXCL_CANCL ,ifnull(sum(FI.