(case when lower(order_status) in (\'delivered\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Delivered_Revenue ,ifnull(sum(case when lower(order_status) in (\'returned\',\'rto\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Returned_Revenue ,ifnull(sum(case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0) end),0) Dispatched_Revenue ,ifnull(sum(case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then ifnull(FI.SELLING_PRICE,0) end),0) Realised_Revenue ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -3 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L3M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -6 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L6M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -12 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L12M_Customers_Retained ,sum(case when lower(FI.new_customer_flag) = \'repeat\' then ifnull(FI.selling_price,0) end) Repeat_Customer_Revenue ,count(distinct case when lower(FI.payment_mode) in (\'cod\') then FI.order_id end) as COD_Orders from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SALES_CONSOLIDATED FI group by 1,2,3,4,5 ), monthly_qty AS ( SELECT DATE_TRUNC(Date, MONTH) AS month, Marketplace, SUM(TOTAL_QUANTITY) AS monthly_total_quantity FROM orders GROUP BY 1,2 ), monthly_qty_mom AS ( SELECT month, Marketplace, monthly_total_quantity, LAG(monthly_total_quantity) OVER ( PARTITION BY Marketplace ORDER BY month ) AS prev_month_qty FROM monthly_qty ), orders_with_mom AS ( SELECT o.*, m.prev_month_qty FROM orders o LEFT JOIN monthly_qty_mom m ON DATE_TRUNC(o.Date, MONTH) = m.month AND LOWER(o.Marketplace) = LOWER(m.Marketplace) ), spendd2c as (select date ,case when lower(channel) like \'%facebook%\' and lower(brand) like \'%db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%google ads - db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%facebook%\' and lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like \'%google ads - ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like \'%amazon%\' then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like \'%myntra%\' then \'MYNTRA\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand ,sum(ifnull(spend,0)) as spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_MARKETING_CONSOLIDATED group by 1,2,3,4 ) select coalesce(fi.Date,MC.date, SC.date) as date, upper(coalesce(fi.marketplace,MC.marketplace,RS.marketplace, SC.marketplace)) as Marketplace, upper(coalesce(fi.marketing_channel,MC.marketing_Channel,RS.marketing_channel, SC.marketing_channel)) as Marketing_Channel, upper(coalesce(fi.brand, mc.brand, rs.brand, sc.brand)) as Brand, Total_Sales, TOTAL_SALES_EXCL_CANCL, Pending_Sales, SC.sessions, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, FI.prev_month_qty, SAFE_DIVIDE( FI.prev_month_qty - TOTAL_QUANTITY, FI.prev_month_qty ) AS MOM_CHANGE_PCT, QUANTITY_EXCL_CANCL, Returned_Orders, RS.TOTAL_RETURNED_QUANTITY as Return_Quantity, RS.TOTAL_RETURN_AMOUNT as Return_Value, FI.Return_Value as Returned_Value, Cancelled_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, Realised_Revenue, spend as marketing_spend, COD_Orders, Repeat_Customer_Revenue, MC.ad_conversions, MC.ad_impressions, MC.ad_clicks, MC.ad_sales, Number_Of_SKU, Sum_Of_COGS, FI.Return_Quantity as New_Returned_Qty, FI.Sub_Category, Case when upper(coalesce(fi.marketplace,MC.marketplace,RS.marketplace, SC.marketplace)) like \'%B2B%\' then \'B2B\' when upper(coalesce(fi.marketplace,MC.marketplace,RS.marketplace, SC.marketplace)) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type from orders_with_mom FI full outer join spendd2c MC on FI.Date = MC.date and lower(FI.marketing_channel)=lower(MC.marketing_channel) and lower(FI.Marketplace)=lower(MC.Marketplace) full outer join returnsales RS on RS.return_date = coalesce(FI.date, MC.date) and lower(RS.marketing_Channel) = lower(coalesce(FI.marketing_Channel,MC.marketing_channel)) and lower(RS.marketplace)=lower(coalesce(FI.marketplace,MC.marketplace)) full outer join SESSIONS SC on coalesce(FI.Date,MC.date,RS.return_date)=SC.Date and lower(coalesce(FI.Marketing_Channel,MC.marketing_channel,RS.marketing_Channel))=lower(SC.Marketing_Channel) and lower(coalesce(FI.marketplace,MC.marketplace,RS.marketplace))=lower(SC.Marketplace) ; create or replace table thd-pharma-wh.MAPLEMONK.channel_targets ( channel string, sales_target float64, spends_target float64, brand string ); INSERT INTO thd-pharma-wh.MAPLEMONK.channel_targets (channel, sales_target, spends_target,brand) values (\'B2B\', 38533765.0,11255805.0,\'DB\'), (\'B2C\', 51779747.0,17407284.0,\'DB\'), (\'D2C\', 30104504.0,30499600.0,\'DB\'), (\'B2C\', 86986168.0,7159598.0,\'OZONE\'), (\'B2B\', 21390041.0,0,\'OZONE\'), (\'D2C\', 34224066.0,29902856.0,\'OZONE\') ; create or replace table thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate as WITH base AS ( SELECT *, CASE WHEN EXTRACT(MONTH FROM date) >= 4 THEN EXTRACT(YEAR FROM date) ELSE EXTRACT(YEAR FROM date) - 1 END AS fy_start_year FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_Sales_Cost_Source ) select date, marketplace, channel_type, marketing_channel, brand, sub_category, ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) - ifnull(pending_sales,0) sales, sum(ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) - ifnull(pending_sales,0)) over (partition by marketing_channel, marketplace, brand, channel_type, sub_category, date_trunc(date, month) order by date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) mtd_sales, sum(ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) - ifnull(pending_sales,0)) OVER (PARTITION BY marketing_channel, marketplace, brand, channel_type, sub_category, fy_start_year ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS fy_ytd_sales, ifnull(marketing_spend,0) as marketing_spend, sum(ifnull(marketing_spend,0)) over (partition by marketing_channel, marketplace, brand, channel_type, sub_category, date_trunc(date, month) order by date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) mtd_spend, sum(ifnull(marketing_spend,0)) OVER (PARTITION BY marketing_channel, marketplace, brand, channel_type, sub_category, fy_start_year ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS fy_ytd_spend from base ; create or replace table thd-pharma-wh.MAPLEMONK.summary_dashboard_table as WITH current_data AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, sales, mtd_sales, fy_ytd_sales, marketing_Spend, mtd_spend, fy_ytd_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ), previous_fy AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, sales AS previous_fy_today_sales, mtd_sales AS previous_fy_mtd_sales, fy_ytd_sales AS previous_fy_ytd_sales, marketing_Spend AS previous_fy_today_marketing_spend, mtd_spend AS previous_fy_mtd_marketing_spend, fy_ytd_spend AS previous_fy_ytd_marketing_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ), previous_month AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, mtd_sales as pmtd_sales, mtd_spend as pmtd_spend, FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ) SELECT coalesce(c.date, date_add(p.date, interval 1 year), date_Add(pm.date, interval 1 month)) AS date, coalesce(c.marketing_channel, p.marketing_channel, pm.marketing_channel) marketing_channel, coalesce(c.marketplace, p.marketplace, pm.marketplace) marketplace, coalesce(c.channel_type, p.channel_type, pm.channel_type) channel_type, coalesce(c.brand, p.brand, pm.brand) brand, coalesce(c.sub_Category, p.sub_Category, pm.sub_Category) sub_Category, c.sales, c.mtd_sales, c.fy_ytd_sales, c.marketing_Spend, c.mtd_spend, c.fy_ytd_spend, p.previous_fy_today_sales, p.previous_fy_mtd_sales, p.previous_fy_ytd_sales, p.previous_fy_today_marketing_spend, p.previous_fy_mtd_marketing_spend, p.previous_fy_ytd_marketing_spend, pm.pmtd_sales, pm.pmtd_spend, case when c.date between \'2026-04-01\' and \'2027-03-31\' then (ct.sales_target / 365.0) / count(*) over (partition by c.channel_type,c.brand, c.date) else null end AS daily_channel_target, ct.sales_target as year_target, ct.spends_target as year_spend_target FROM current_data c left join thd-pharma-wh.maplemonk.channel_targets ct on upper(c.channel_type) = upper(ct.channel) and upper(c.brand) = upper(ct.brand) full outer join previous_fy p ON p.date = DATE_SUB(c.date, INTERVAL 1 YEAR) AND p.marketing_channel = c.marketing_channel AND p.marketplace = c.marketplace and p.brand = c.brand and p.sub_Category = c.sub_Category and p.channel_type = c.channel_type full outer join previous_month pm ON pm.date = DATE_SUB(c.date, INTERVAL 1 MONTH) AND pm.marketing_channel = c.marketing_channel AND pm.marketplace = c.marketplace and pm.brand = c.brand and pm.sub_Category = c.sub_Category and pm.channel_type = c.channel_type order by coalesce(c.date, date_add(p.date, interval 1 year), date_Add(pm.date, interval 1 month)) desc ;",
